package main

import (
	"fmt"
	"time"
)

func main() {
	work := make(chan string)
	go func() {
		time.Sleep(50 * time.Millisecond) // too slow
		work <- "done"
	}()
	select {
	case v := <-work:
		fmt.Println(v)
	case <-time.After(10 * time.Millisecond):
		fmt.Println("timed out")
	}
	// Output: timed out
}

package main

import "fmt"

func main() {
	done := make(chan struct{})
	jobs := make(chan int, 3)
	jobs <- 1
	jobs <- 2
	close(done) // signal stop after loading jobs
	total := 0
	for {
		select {
		case <-done:
			fmt.Println(total)
			return
		case v := <-jobs:
			total += v
		}
	}
	// Output: 0   (done is ready immediately; may vary)
}

