package main

import (
	"fmt"
	"sync"
	"time"
)

func main() {
	done := make(chan struct{})
	ticks := time.Tick(10 * time.Millisecond)
	var mu sync.Mutex
	count := 0
	go func() {
		for {
			select {
			case <-done:           // cancellation: clean exit
				return
			case <-ticks:          // periodic work
				mu.Lock()
				count++
				mu.Unlock()
			}
		}
	}()
	time.Sleep(35 * time.Millisecond)
	close(done)                        // tell the loop to stop
	time.Sleep(10 * time.Millisecond)
	mu.Lock()
	fmt.Println("stopped, ticks >=", count >= 1)
	mu.Unlock()
}

