package solution

import "time"

func Solve(ch <-chan int, timeout time.Duration) []int {
	out := make([]int, 0)
	deadline := time.After(timeout)   // fires once after `timeout`
	for {
		select {
		case v, ok := <-ch:
			if !ok {              // channel closed & drained
				return out
			}
			out = append(out, v)
		case <-deadline:          // ran out of time
			return out
		}
	}
}

