package solution

import (
	"reflect"
	"testing"
	"time"
)

func TestSolve(t *testing.T) {
	// closes before timeout -> gets all values
	ch := make(chan int, 3)
	ch <- 1
	ch <- 2
	ch <- 3
	close(ch)
	if got := Solve(ch, time.Second); !reflect.DeepEqual(got, []int{1, 2, 3}) {
		t.Errorf("closed case: got %v want [1 2 3]", got)
	}

	// never closes -> times out and returns what it has
	ch2 := make(chan int, 1)
	ch2 <- 9
	got := Solve(ch2, 20*time.Millisecond)
	if len(got) != 1 || got[0] != 9 {
		t.Errorf("timeout case: got %v want [9]", got)
	}
}

