func worker(jobs <-chan int, done <-chan struct{}) {
	for {
		select {
		case <-done:                 // cancellation: clean exit
			return
		case j, ok := <-jobs:
			if !ok {                 // jobs closed & drained
				return
			}
			process(j)
		}
	}
}

func OrDone(done <-chan struct{}, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for {
			select {
			case <-done:               // cancelled: stop forwarding
				return
			case v, ok := <-in:
				if !ok {               // input drained
					return
				}
				select {               // forward, but stay cancellable
				case out <- v:
				case <-done:
					return
				}
			}
		}
	}()
	return out
}

func Merge(done <-chan struct{}, a, b <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for a != nil || b != nil {
			select {
			case <-done: // cancelled: stop forwarding
				return
			case v, ok := <-a:
				if !ok {
					a = nil // disable this case
					continue
				}
				select {
				case out <- v:
				case <-done:
					return
				}
			case v, ok := <-b:
				if !ok {
					b = nil // disable this case
					continue
				}
				select {
				case out <- v:
				case <-done:
					return
				}
			}
		}
	}()
	return out
}
